-- V8 标准审计字段、乐观锁、逻辑删除及AI付款重建上限。
ALTER TABLE t_user_favorite DROP PRIMARY KEY, ADD COLUMN id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY FIRST;
ALTER TABLE t_user_favorite ADD UNIQUE KEY uk_favorite_pair(user_id,post_id);
ALTER TABLE t_user_favorite ADD COLUMN update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
ALTER TABLE t_user_favorite ADD COLUMN create_by BIGINT NULL, ADD COLUMN update_by BIGINT NULL, ADD COLUMN is_deleted TINYINT NOT NULL DEFAULT 0, ADD COLUMN version INT NOT NULL DEFAULT 0;
ALTER TABLE t_feedback ADD COLUMN create_by BIGINT NULL, ADD COLUMN update_by BIGINT NULL, ADD COLUMN is_deleted TINYINT NOT NULL DEFAULT 0, ADD COLUMN version INT NOT NULL DEFAULT 0;
ALTER TABLE t_feedback_reply ADD COLUMN update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
ALTER TABLE t_feedback_reply ADD COLUMN create_by BIGINT NULL, ADD COLUMN update_by BIGINT NULL, ADD COLUMN is_deleted TINYINT NOT NULL DEFAULT 0, ADD COLUMN version INT NOT NULL DEFAULT 0;
ALTER TABLE t_pet_room DROP PRIMARY KEY, ADD COLUMN id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY FIRST;
ALTER TABLE t_pet_room ADD UNIQUE KEY uk_room_pet(pet_id);
ALTER TABLE t_pet_room ADD COLUMN create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE t_pet_room ADD COLUMN update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
ALTER TABLE t_pet_room ADD COLUMN create_by BIGINT NULL, ADD COLUMN update_by BIGINT NULL, ADD COLUMN is_deleted TINYINT NOT NULL DEFAULT 0, ADD COLUMN version INT NOT NULL DEFAULT 0;
ALTER TABLE t_reward_dispute ADD COLUMN create_by BIGINT NULL, ADD COLUMN update_by BIGINT NULL, ADD COLUMN is_deleted TINYINT NOT NULL DEFAULT 0, ADD COLUMN version INT NOT NULL DEFAULT 0;
ALTER TABLE t_conversation ADD COLUMN update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
ALTER TABLE t_conversation ADD COLUMN create_by BIGINT NULL, ADD COLUMN update_by BIGINT NULL, ADD COLUMN is_deleted TINYINT NOT NULL DEFAULT 0, ADD COLUMN version INT NOT NULL DEFAULT 0;
ALTER TABLE t_conversation_message ADD COLUMN update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
ALTER TABLE t_conversation_message ADD COLUMN create_by BIGINT NULL, ADD COLUMN update_by BIGINT NULL, ADD COLUMN is_deleted TINYINT NOT NULL DEFAULT 0, ADD COLUMN version INT NOT NULL DEFAULT 0;
ALTER TABLE t_pet_avatar_task ADD COLUMN create_by BIGINT NULL, ADD COLUMN update_by BIGINT NULL, ADD COLUMN is_deleted TINYINT NOT NULL DEFAULT 0, ADD COLUMN version INT NOT NULL DEFAULT 0;
ALTER TABLE t_pet_avatar_task ADD COLUMN pay_rebuild_count INT NOT NULL DEFAULT 0;
ALTER TABLE t_reward_dispute ADD COLUMN pending_guard TINYINT GENERATED ALWAYS AS (CASE WHEN status='PENDING' AND is_deleted=0 THEN 1 ELSE NULL END) STORED, ADD UNIQUE KEY uk_dispute_pending(post_id,user_id,pending_guard);
